SELECT ?zone ?zone_name ?sensor ?ts_id WHERE {
  ?sensor a brick:AirTemperatureSensor ;
          brick:measures ?point .
  ?zone a brick:Zone .
  ?point ref:hasLocation ?zone .
  ?zone rdfs:label ?zone_name .
  ?sensor ref:hasExternalReference ?ext .
  ?ext ref:hasTimeseriesId ?ts_id .
}

SELECT ?point ?pt_class ?zone ?zname WHERE {
  ?pt a brick:AirTemperature .
  ?pt brick:hasLocation ?zone .
  ?zone rdfs:label ?zname .
  BIND(?pt AS ?point)
} LIMIT 40

SELECT ?point ?type ?zone ?zname WHERE {
  ?point rdf:type/a brick:AirTemperature .
  ?point brick:hasLocation ?zone .
  ?zone rdfs:label ?zname .
} LIMIT 40

